namespace ghidra.app.cmd.function;

using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;

/**
 * Command to set the name of a function.
 */
public class SetFunctionNameCmd : Command<Program> {
	private Address entry;
	private string name;
	private string msg;
	private SourceType source;

	/**
	 * Constructs a new command for setting the name of a function.
	 * @param entry the address of the function to be renamed.
	 * @param newName the new name for the function.
	 * @param source the source of this function name
	 */
	public SetFunctionNameCmd(Address entry, string newName, SourceType source) {
		this.entry = entry;
		this.name = newName;
		this.source = source;
	}

	/* @Override */
	public bool applyTo(Program program) {

		if (name.length() <= 0) {
			name = null;
		}

		Function f = program.getListing().getFunctionAt(entry);
		if (f == null) {
			return true;
		}
		try {
			f.setName(name, source);
		}
		catch (Exception e) {
			msg = e.getMessage();
			return false;
		}
		return true;

	}

	/* @Override */
	public string getName() {
		return "Rename Function";
	}

	/* @Override */
	public string getStatusMsg() {
		return msg;
	}

}
